import pandas as pd


def analyze_football_trends():
    filename = "kenya_football_google_trends.csv"

    try:
        # Load the CSV file generated by pytrends, setting date as the index
        df = pd.read_csv(filename, parse_dates=['date'], index_col='date')
    except FileNotFoundError:
        print(f"Error: Could not find '{filename}'. Make sure you ran your data collection script first!")
        return

    print("=== KENYAN FOOTBALL GOOGLE TRENDS: STATISTICAL ANALYSIS ===")
    print(f"Timeframe analyzed: {df.index.min().strftime('%Y-%m-%d')} to {df.index.max().strftime('%Y-%m-%d')}\n")

    # 1. Calculate Average Relative Interest (Mean)
    mean_interest = df.mean().sort_values(ascending=False)
    print("--- Average Relative Search Interest (0-100 Scale) ---")
    for keyword, score in mean_interest.items():
        print(f"{keyword:<25}: {score:.2f}")

    print("\n--- Peak Search Spikes (Maximum Interest Recorded) ---")
    # 2. Identify Peak Spikes and the dates they occurred
    for col in df.columns:
        max_val = df[col].max()
        peak_date = df[col].idxmax().strftime('%Y-%m-%d')
        print(f"{col:<25}: Peak Score of {max_val} on {peak_date}")

    print("\n--- Volatility / Standard Deviation (Search Stability vs. Hype) ---")
    # 3. Calculate Standard Deviation to measure how spiky/volatile interest is
    volatility = df.std().sort_values(ascending=False)
    for keyword, std_val in volatility.items():
        print(f"{keyword:<25}: Std Dev = {std_val:.2f}")


if __name__ == "__main__":
    analyze_football_trends()